import{_ as t,o as s,c as n,a2 as o}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Common errors and solutions when running AzureScout.","frontmatter":{"description":"Common errors and solutions when running AzureScout."},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),a={name:"guide/troubleshooting.md"};function r(i,e,d,l,c,p){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="common-errors" tabindex="-1">Common Errors <a class="header-anchor" href="#common-errors" aria-label="Permalink to &quot;Common Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Insufficient privileges to complete the operation</code></td><td>Missing Microsoft Graph permission</td><td>Grant the required permission and perform admin consent. See <a href="./permissions.html">Permissions</a>.</td></tr><tr><td><code>Authorization_RequestDenied</code></td><td>Delegated permission not consented</td><td>Sign in with a Global Admin and consent to the required permissions.</td></tr><tr><td><code>Resource provider not registered</code> / <code>[FAIL] Provider: ... NotRegistered</code></td><td>Provider not enabled in subscription</td><td><strong>This is expected.</strong> Not all providers need to be registered in every subscription — Azure only registers providers for services you actually use. The corresponding inventory modules are simply skipped. Only register a provider if you actually use that service and want it included in the report: <code>Register-AzResourceProvider -ProviderNamespace &lt;namespace&gt;</code>. See <a href="./prerequisites.html">Prerequisites</a> for details.</td></tr><tr><td><code>No match was found for the specified search criteria and module name</code></td><td>Module not available in PSGallery or network restrictions</td><td>Install the module manually. See <a href="./prerequisites.html">Prerequisites</a> for install commands.</td></tr><tr><td><code>Get-AzSubscription returned 0 subscriptions</code></td><td>Identity has no Reader role on any subscription</td><td>Assign <code>Reader</code> at the subscription or management group level.</td></tr><tr><td><code>Connect-AzAccount: interactive login failed</code></td><td>Running in a non-interactive session (CI/CD, SSH)</td><td>Use <code>-DeviceLogin</code>, SPN with secret, or SPN with certificate. See <a href="./authentication.html">Authentication</a>.</td></tr><tr><td><code>Token acquisition failed for MSGraph</code></td><td>Az.Accounts version too old or tenant configuration issue</td><td>Update <code>Az.Accounts</code> to latest: <code>Update-Module Az.Accounts -Force</code></td></tr><tr><td><code>Export-Excel: file is locked</code> during an internal compatibility test</td><td>A fixture from the held Excel renderer is open in another application; live runs do not emit Excel</td><td>Close the fixture and re-run the renderer test.</td></tr><tr><td>Management groups, custom roles, or policy definitions are absent from React/JSON</td><td>First check: is <code>Reader</code> assigned at the <strong>tenant-root management group</strong>, not just at individual subscriptions? Subscription-scoped <code>Reader</code> silently returns an empty hierarchy — no error.</td><td>Assign <code>Reader</code> at the tenant-root MG. Since v2.3.0 the login summary reports the visible management-group count at sign-in. If root-MG <code>Reader</code> is already in place and the data is still empty, that&#39;s worth reporting — whether <code>Management Group Reader</code> is genuinely additional beyond <code>Reader</code> is currently unresolved; see <a href="./permissions.html#arm-permissions">Permissions</a>. Do not reach for a broader role first.</td></tr><tr><td>A Graph-backed collector (e.g. <code>IdentityProviders</code>) is empty and nothing seems wrong with permissions</td><td>Some Graph queries are issued but consumed by no collector — Scout still probes them so the pre-flight can tell you they&#39;re unnecessary</td><td>Expected. The pre-flight prints <code>Warn ... queried but NO collector reads the result. Do not grant it.</code> for these — check <code>-PermissionAudit</code> / <code>Test-AZSCPermissions</code> output rather than granting more access. See <a href="./permissions.html#microsoft-graph-permissions">Permissions</a>.</td></tr><tr><td><code>Get-AzAdvisorRecommendation_List: ... Expected &#39;{&#39; or &#39;[&#39;. Was String: The.</code></td><td>A defect in <code>Az.Advisor</code> 3.0.0, not in Scout. Azure returned a plain-text error sentence beginning &quot;The …&quot; — almost always <code>Microsoft.Advisor</code> not being registered on that subscription, or Advisor not having assessed it yet — and the generated cmdlet deserialises it as JSON regardless.</td><td><strong>Expected and handled since v3.3.2.</strong> Scout skips that subscription, names it, and carries on; the other subscriptions are unaffected and the missing findings are reported as <em>Not assessed</em>. To include it: <code>Register-AzResourceProvider -ProviderNamespace Microsoft.Advisor</code>. To omit Advisor entirely: <code>-SkipAdvisory</code>. Before v3.3.2 this aborted the Advisor sweep for the <strong>whole tenant</strong> and surfaced as a raw stack trace.</td></tr><tr><td><code>[FAIL] Graph: IdentityRiskyUser.Read.All: DENIED</code> on a tenant that has consented to it</td><td>Identity Protection is an <strong>Entra ID P2</strong> feature. Without P2 the endpoint returns nothing no matter how much consent is granted.</td><td><strong>Not a permission problem — do not chase it.</strong> Since v3.3.2 Scout reads <code>subscribedSkus</code> and reports <code>NOT LICENSED — requires Microsoft Entra ID P2</code> instead, and <code>Identity/RiskyUsers</code> is reported as <em>Not assessed</em>. Granting the permission does not populate it; only a P2 licence does. See <a href="./permissions.html#licence-tiers-what-a-permission-cannot-buy-you">Permissions</a>.</td></tr><tr><td>Cost data is empty despite <code>Reader</code> (and even <code>Cost Management Reader</code>) being assigned</td><td>Cost visibility is gated on a <strong>billing setting</strong>, not a role: EA &quot;AO view charges&quot; or MCA &quot;Azure charges&quot;</td><td>Have a billing administrator (Enterprise Administrator for EA, <strong>Billing Profile Owner</strong> for MCA) enable the setting. No Azure RBAC role change fixes this. See <a href="./permissions.html#arm-permissions">Permissions</a>.</td></tr><tr><td>Reports are not where a previous version left them</td><td>Run isolation (v2.3.0)</td><td>Each run now writes to its own folder under the base path. Use <code>-Force</code> for the old overwrite-in-place behaviour, or <code>-RunName</code> to control the folder name. See <a href="./output.html#run-isolation">Output Files &amp; Formats</a>.</td></tr><tr><td>Output folders accumulating on disk</td><td>One folder per run, by design</td><td><code>Clear-AZSCCacheFolder -OlderThan 30</code> prunes runs not written to in the last 30 days.</td></tr><tr><td><code>No Azure DevOps organizations could be discovered</code></td><td>Service principals have no profile to enumerate</td><td>Pass <code>-DevOpsOrganization &#39;contoso&#39;,&#39;fabrikam&#39;</code>. See <a href="./../automation-guide/azure-devops.html">Azure DevOps</a>.</td></tr><tr><td><code>Could not acquire an Azure DevOps token</code></td><td>Not signed in, or the sign-in cannot reach Azure DevOps</td><td>Run <code>Connect-AzAccount</code>, or pass <code>-DevOpsPat</code>.</td></tr><tr><td>ADO Service Connections data missing</td><td>Identity holds project read but not service connection read</td><td>Expected and handled — that slice is skipped and the rest still collects. Grant the scope to include it.</td></tr><tr><td>Runbook uploads fail with <code>blob already exists</code></td><td>Module older than v2.3.0</td><td>Upgrade. Uploads now pass <code>-Force</code>, so a second scheduled run overwrites rather than failing. See <a href="./../automation-guide/automation.html">Azure Automation Account</a>.</td></tr><tr><td>A held Excel-renderer compatibility test reports <code>0x80040154 REGDB_E_CLASSNOTREG</code></td><td>Obsolete module/test path attempted Excel COM</td><td>Upgrade the test target. The retained renderer uses EPPlus/ImportExcel; live React/JSON runs do not execute chart customization.</td></tr><tr><td><code>The term &#39;Invoke-AzCostManagementQuery&#39; is not recognized</code></td><td><code>Az.CostManagement</code> missing, and before v2.5.3 <code>-IncludeCosts</code> treated that as fatal</td><td>Upgrade. Since v2.5.3 the run continues without cost data and warns instead. To collect costs, <code>Install-Module Az.CostManagement -Scope CurrentUser</code>.</td></tr><tr><td><code>The property &#39;&lt;name&gt;&#39; cannot be found on this object</code> during extraction</td><td>Module older than v2.5.3</td><td>Upgrade. This was a StrictMode member-enumeration fault that fired whenever an Azure API returned an empty result for <strong>every</strong> subscription — see <a href="./../project/changelog.html">Changelog</a>.</td></tr></tbody></table><h2 id="run-logs" tabindex="-1">Run logs <a class="header-anchor" href="#run-logs" aria-label="Permalink to &quot;Run logs&quot;">​</a></h2><p><strong>Every run writes a detailed log into its own run folder — you do not have to ask for it.</strong> When something goes wrong, read the log before re-running anything.</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>scout-run.log</code></td><td>Structured detailed log: run metadata; DEBUG/VERBOSE extraction subphases; collector status, rows, and elapsed time; processing and assessment timing; per-rule evidence counts; renderer completion; warnings; and, on failure, the full error record including script, line, and stack trace. This detail is written by default without enabling console <code>-Debug</code> or <code>-Verbose</code>.</td></tr><tr><td><code>scout-console.log</code></td><td>Transcript of everything printed to the console, warnings included. Skipped on hosts that do not support transcription (including Azure Automation)</td></tr></tbody></table><p>Both land next to the live outputs:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\Users\\you\\Documents\\AzureScout\\2026-07-25_152431_d6fc73cf\\</span></span>
<span class="line"><span>├── scout-run.log</span></span>
<span class="line"><span>├── scout-console.log</span></span>
<span class="line"><span>├── report-react.html</span></span>
<span class="line"><span>├── AzureScout_Report_2026-07-25_15_24.json</span></span>
<span class="line"><span>└── evidence.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>A failed run prints the log path before it exits:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  The run failed. Full detail written to: C:\\...\\2026-07-25_152431_d6fc73cf\\scout-run.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The failure block in <code>scout-run.log</code> looks like this — the script and line are the fastest route to a diagnosis, and are exactly what a bare console error does not give you:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[2026-07-25 15:58:09.445] [ERROR] ---------------- RUN FAILED ----------------</span></span>
<span class="line"><span>[2026-07-25 15:58:09.476] [ERROR] Message    : The term &#39;Invoke-AzCostManagementQuery&#39; is not recognized...</span></span>
<span class="line"><span>[2026-07-25 15:58:09.587] [ERROR] Script     : ...\\Modules\\Private\\Extraction\\Get-AZTICostInventory.ps1</span></span>
<span class="line"><span>[2026-07-25 15:58:09.620] [ERROR] Line       : 49</span></span>
<span class="line"><span>[2026-07-25 15:58:09.682] [ERROR] ScriptStackTrace :</span></span>
<span class="line"><span>[2026-07-25 15:58:09.711] [ERROR]     at Get-AZSCCostInventory, ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Logging is best-effort by design: if the log cannot be written the run still proceeds, warning once. A lost log is a lost diagnostic, never a lost report.</p><h2 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h2><p>The file log already contains DEBUG/VERBOSE detail. To mirror additional step-by-step diagnostics to the console while the run is active, enable debug output:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;00000000-...&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Debug</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This produces timestamped log entries for each extraction step, module execution, and API call.</p><h2 id="a-worksheet-looks-wrong-after-upgrading-—-force-the-previous-collector-engine" tabindex="-1">A worksheet looks wrong after upgrading — force the previous collector engine <a class="header-anchor" href="#a-worksheet-looks-wrong-after-upgrading-—-force-the-previous-collector-engine" aria-label="Permalink to &quot;A worksheet looks wrong after upgrading — force the previous collector engine&quot;">​</a></h2><p>Most inventory collectors are defined declaratively (<code>manifests/collectors/&lt;Category&gt;/&lt;Name&gt;.psd1</code>) and executed by a shared interpreter rather than by their own script. Each definition is proven to produce the same rows as the script it replaced, and a full processing pass produces a byte-identical report cache either way — but if a worksheet ever looks wrong and you need to rule the interpreter out, set this before the run:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AZURESCOUT_FORCE_IMPERATIVE_COLLECTORS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;00000000-...&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Every collector then runs as its original script, exactly as releases up to v2.9.0 did. Accepted values are <code>1</code>, <code>true</code>, <code>yes</code> and <code>on</code> (case-insensitive); anything else — including <code>0</code> and <code>false</code> — leaves the normal path in place. Clear it with <code>Remove-Item Env:\\AZURESCOUT_FORCE_IMPERATIVE_COLLECTORS</code>.</p><p>If that changes the output, the difference is a genuine defect worth reporting: attach the worksheet and the collector name.</p><p>The run log records which engine ran each collector — look for <code>Collectors declarative</code> and <code>Collectors imperative</code> in the processing phase summary.</p><h2 id="pre-flight-permission-check" tabindex="-1">Pre-flight Permission Check <a class="header-anchor" href="#pre-flight-permission-check" aria-label="Permalink to &quot;Pre-flight Permission Check&quot;">​</a></h2><p>Run the permission checker standalone to validate access before a full inventory:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Test-AZSCPermissions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;00000000-...&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope All</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Format-List</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The <code>Details</code> array contains per-check results with remediation guidance for any failures. The output is a per-collector impact table, not a bare READY/PARTIAL/INSUFFICIENT verdict — a denied permission names the exact collectors that will come back empty rather than a generic warning. A denied Microsoft Graph permission also reaches PowerShell&#39;s warning stream, so a scripted caller (a pipeline step, a scheduled Automation Account run) can detect it with <code>-WarningVariable</code> or by capturing stream 3, not only a human watching coloured console output. See <a href="./permissions.html#pre-flight-validation">Permissions</a>.</p><h2 id="complete-removal-uninstall" tabindex="-1">Complete Removal (Uninstall) <a class="header-anchor" href="#complete-removal-uninstall" aria-label="Permalink to &quot;Complete Removal (Uninstall)&quot;">​</a></h2><p>If you need to completely remove Azure Scout and ensure no old, cached modules are loaded in future sessions, run the following commands. This forces PowerShell to unload the module from memory, uninstalls all registered versions, and physically deletes any lingering cached folders across your module paths.</p><p>\`powershell</p><h1 id="_1-unload-from-current-active-memory" tabindex="-1">1. Unload from current active memory <a class="header-anchor" href="#_1-unload-from-current-active-memory" aria-label="Permalink to &quot;1. Unload from current active memory&quot;">​</a></h1><p>Remove-Module AzureScout -ErrorAction SilentlyContinue</p><h1 id="_2-uninstall-all-registered-versions" tabindex="-1">2. Uninstall all registered versions <a class="header-anchor" href="#_2-uninstall-all-registered-versions" aria-label="Permalink to &quot;2. Uninstall all registered versions&quot;">​</a></h1><p>Uninstall-Module AzureScout -AllVersions -Force -ErrorAction SilentlyContinue</p><h1 id="_3-aggressively-hunt-down-and-delete-any-physical-artifact-folders-left-behind" tabindex="-1">3. Aggressively hunt down and delete any physical artifact folders left behind <a class="header-anchor" href="#_3-aggressively-hunt-down-and-delete-any-physical-artifact-folders-left-behind" aria-label="Permalink to &quot;3. Aggressively hunt down and delete any physical artifact folders left behind&quot;">​</a></h1><p>$modulePaths = ($env:PSModulePath -split &#39;;&#39;) | Where-Object { $_ -ne &#39;&#39; } foreach ($path in $modulePaths) { $target = Join-Path $path &quot;AzureScout&quot; if (Test-Path $target) { Remove-Item -Path $target -Recurse -Force -ErrorAction SilentlyContinue } } \`</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Once you run these commands, you <strong>must close your PowerShell terminal completely</strong> and open a new one to fully flush the session cache.</p></div>`,37)])])}const g=t(a,[["render",r]]);export{u as __pageData,g as default};
